//! ONE token-value factory for actual physical and initial-definition events.
//! It consumes SAME native lexer facts; it does not scan boundaries, parse
//! expressions, dispatch directives, read files, or grant CODE/model/EOF roles.
use super::original_raw_frame::{OriginalPhysicalLexeme,OriginalRawLexer,OriginalRawNotice};
use super::original_lexical_frame::OriginalLexicalFrameIdentity;
use crate::macro_expansion::{OriginalMacroToken as Token,OriginalMacroValue as Value,OriginalMacroTextValue as Text,OriginalMacroOrigin as Origin,OriginalMacroText,OriginalMacroRows,OriginalMacroDefinition,OriginalMacroNumber,original_quoted_value_using,original_comment_value_using,original_resource_value_using};
use dm_syntax::{SettingAdmission,Span,TokenKind,OriginalQuotedPartKind,OriginalLexicalNoticePoint};
use dm_syntax::numeric_form::{OriginalNumber,OriginalNumberNotice};
use std::io;
fn poll(a:&SettingAdmission<'_>)->io::Result<()>{a.checkpoint().map_err(|e|a.take_operational_error().unwrap_or(e))}
/// Geometry DATA only. Physical variant borrows an actual opened lexer frame;
/// the source owner authenticates that same acquisition before invoking us.
/// Initial definitions have no acquisition/frame/span or physical-final-EOF.
pub(super) enum Geometry<'a>{Physical{origin:Origin,frame:&'a OriginalLexicalFrameIdentity},InitialDefinition}
fn text(value:&str,a:&SettingAdmission<'_>)->io::Result<Text<'static>>{let mut text=OriginalMacroText::new(a)?;text.push_str(value,a)?;Ok(Text::Owned(text))}
/// A resource/value alias only, never a source grant. Normal UTF8 raw loans
/// are already exactly the SAME retained SourceText backing. Avoid allocating
/// one String per queued identifier; exceptional/BOM geometry is never guessed.
fn actual_ident_text(name:&str,span:Span,bytes:&[u8],geometry:&Geometry<'_>,a:&SettingAdmission<'_>)->io::Result<Text<'static>>{
 if let Geometry::Physical{frame,..}=geometry{
  if !frame.admitted_by(a){return Err(io::ErrorKind::InvalidInput.into())}let acquired=frame.acquisition();
  if matches!(acquired.encoding(),crate::SourceEncoding::Utf8|crate::SourceEncoding::SyntheticUtf8)&&std::ptr::eq(bytes,acquired.source_text().as_bytes()){
   let source=acquired.source_text().checked_view(span.range()).ok_or(io::ErrorKind::InvalidInput)?;return Ok(Text::Source(source))
  }
 }text(name,a)
}
fn token(value:Value<'static>,span:Span,closed:bool,raw:&[u8],geometry:Geometry<'_>,a:&SettingAdmission<'_>)->io::Result<Token<'static>>{
 let(origin,lexical_frame,lexical_span,initial)=match geometry{Geometry::Physical{mut origin,frame}=>{if !frame.admitted_by(a){return Err(io::Error::new(io::ErrorKind::InvalidInput,"actual token factory has another physical frame resource owner"))}origin.physical=span;(origin,Some(frame.clone()),Some(span),false)},Geometry::InitialDefinition=>(Origin{physical:Span::default(),line:0,byte_column:None,occurrence:0,invocation:false},None,None,true)};
 // Physical spellings are lent only later by the SAME frame+raw extent, not
 // reencoded into fake SourceText aliases. Nonphysical config has no such loan;
 // retain exact UTF8 spelling when representable, distinct from typed value.
 let raw_spelling=if initial{match std::str::from_utf8(raw){Ok(raw)=>Some(text(raw,a)?),Err(_)=>None}}else{None};
 Ok(Token{string_mode:dm_syntax::OriginalStringMode::Unknown,punctuation_close:closed,lexical_frame,lexical_span,value,raw_spelling,origin})
}
/// Numeric conversion notices are not emitted by the raw boundary lexer. They
/// retain its actual notice descriptor and the SAME already-parsed normalized
/// value; the actual source owner records severity/type/message before commit.
/// Other raw lexical notices are emitted exactly once by RawLexer, not here.
pub(super) fn project_using(event:OriginalPhysicalLexeme<'_>,bytes:&[u8],geometry:Geometry<'_>,a:&SettingAdmission<'_>,numeric:&mut dyn FnMut(OriginalLexicalNoticePoint,OriginalNumberNotice<'_>)->io::Result<()>)->io::Result<Option<Token<'static>>>{
 poll(a)?;match event{
  OriginalPhysicalLexeme::FinalNewline{at}=>token(Value::Punct("\n"),Span::new(at,at),false,b"",geometry,a).map(Some),
  OriginalPhysicalLexeme::Quote(part)|OriginalPhysicalLexeme::QuoteFailure{recovery:part,..}=>{let value=original_quoted_value_using(&part,a)?;if value.lexical.is_err(){return Err(io::Error::new(io::ErrorKind::Unsupported,"actual Original quote issuer has an unissued lexical value projection"))}let text=Text::Owned(value.text);let value=match value.kind{OriginalQuotedPartKind::String=>Value::String(text),OriginalQuotedPartKind::Begin=>Value::InterpBegin(text),OriginalQuotedPartKind::Part=>Value::InterpPart(text),OriginalQuotedPartKind::End=>Value::InterpEnd(text)};{let mut token=token(value,part.token_span(),false,part.raw_spelling(),geometry,a)?;token.string_mode=if part.is_raw(){dm_syntax::OriginalStringMode::Raw}else{dm_syntax::OriginalStringMode::Normal};Ok(Some(token))}},
  OriginalPhysicalLexeme::Scalar{token:issued,number,comment,resource,punctuation,ident,whitespace}=>{
   let span=issued.span;let raw=bytes.get(span.range()).ok_or(io::ErrorKind::InvalidInput)?;
   let(value,closed)=match issued.kind{
    TokenKind::Ident=>{let facts=ident.ok_or_else(||io::Error::new(io::ErrorKind::InvalidData,"actual Original Ident lacks its issued lexical facts"))?;if facts.span()!=span{return Err(io::ErrorKind::InvalidInput.into())}let name=std::str::from_utf8(raw).map_err(|_|io::Error::new(io::ErrorKind::InvalidData,"actual ASCII Original Ident contains non-ASCII bytes"))?;if name=="in"{(Value::Punct("in"),false)}else{(Value::Ident{spelling:actual_ident_text(name,span,bytes,&geometry,a)?,whitespace:facts.whitespace()},false)}},
    TokenKind::Number=>{let facts=number.ok_or_else(||io::Error::new(io::ErrorKind::InvalidData,"actual Original Number lacks its issued lexical facts"))?;if facts.span()!=span{return Err(io::ErrorKind::InvalidInput.into())}let number=OriginalMacroNumber::from_issued_facts_using(facts,bytes,a)?;if let Some(notice)=number.notice(){numeric(facts.notice_point(),notice)?;}let value=match number.value(){OriginalNumber::Integer(n)=>Value::Int(n),OriginalNumber::Float(n)=>Value::Float(n)};(value,false)},
    TokenKind::Resource=>{let facts=resource.ok_or_else(||io::Error::new(io::ErrorKind::InvalidData,"actual Original Resource lacks its issued lexical facts"))?;if facts.span()!=span{return Err(io::ErrorKind::InvalidInput.into())}(Value::Resource(Text::Owned(original_resource_value_using(facts,bytes,a)?)),false)},
    TokenKind::Comment=>{let facts=comment.ok_or_else(||io::Error::new(io::ErrorKind::InvalidData,"actual Original Comment lacks its issued lexical facts"))?;if facts.span()!=span{return Err(io::ErrorKind::InvalidInput.into())}let Some(value)=original_comment_value_using(facts,bytes,a)?else{return Ok(None)};(Value::DocComment{kind:facts.kind(),text:Text::Owned(value)},false)},
    TokenKind::Whitespace=>{let facts=whitespace.ok_or_else(||io::Error::new(io::ErrorKind::InvalidData,"unissued interior whitespace reached Original token factory"))?;if facts.span()!=span{return Err(io::ErrorKind::InvalidInput.into())}(Value::Punct(if facts.tab(){"\t"}else{" "}),false)},
    TokenKind::Newline=>(Value::Punct("\n"),false),
    TokenKind::Operator|TokenKind::Punctuation=>{let facts=punctuation.ok_or_else(||io::Error::new(io::ErrorKind::InvalidData,"actual Original punctuation lacks its issued lexical facts"))?;if facts.span()!=span{return Err(io::ErrorKind::InvalidInput.into())}(Value::Punct(facts.spelling()),facts.closed())},
    TokenKind::Unknown|TokenKind::String|TokenKind::Interpolation=>return Err(io::Error::new(io::ErrorKind::Unsupported,"actual Original raw driver yielded an unissued scalar instead of its canonical token event")),
   };token(value,span,closed,raw,geometry,a).map(Some)
  }
 }
}

/// Actual one-time bootstrap issuer. The definition view is created only by
/// the authenticated existing configuration walk, and lexical/value processing
/// is the SAME kernel used by real physical frames. No #define source wrapper,
/// fake source acquisition/BOM/final newline, or lookup-time relex is involved.
pub(super) fn initial_definition_using(input:crate::initial_environment::OriginalInitialDefinition<'_>,a:&SettingAdmission<'_>,lexical:&mut dyn FnMut(OriginalRawNotice)->io::Result<()>,numeric:&mut dyn FnMut(OriginalLexicalNoticePoint,OriginalNumberNotice<'_>)->io::Result<()>)->io::Result<OriginalMacroDefinition<'static>>{
 poll(a)?;let metadata=input.metadata();let parameters=match &metadata.parameters{None=>None,Some(names)=>{let mut parameters=OriginalMacroRows::new(a)?;for name in names{let mut owned=OriginalMacroText::new(a)?;owned.push_str(name,a)?;parameters.push(owned,a)?;}Some(parameters)}};
 let mut replacement=OriginalMacroRows::new(a)?;let mut lexer=OriginalRawLexer::for_initial_definition(a)?;
 while let Some(projected)=lexer.next_using(input.replacement_text().as_bytes(),a,&mut *lexical,|event,bytes|{if matches!(&event,OriginalPhysicalLexeme::FinalNewline{..}){return Err(io::Error::new(io::ErrorKind::InvalidData,"initial definition lexer invented a physical final newline"))}project_using(event,bytes,Geometry::InitialDefinition,a,&mut *numeric)})?{if let Some(token)=projected{replacement.push_definition_row(token,a)?;}}
 Ok(OriginalMacroDefinition{parameters,variadic:metadata.variadic,replacement})
}

#[cfg(test)]#[path="../../../../fixtures/original_default_macro_products.rs"]mod immutable_original_defaults;
#[cfg(test)]mod tests{
 use super::*;use std::{collections::BTreeMap,sync::{Arc,atomic::{AtomicUsize,Ordering}}};
 fn actual_table(caller:&BTreeMap<String,String>)->BTreeMap<String,crate::Macro>{let mut rows=BTreeMap::new();crate::initial_environment::install(crate::InitialEnvironment::OriginalChecker0290,&mut rows);for(name,replacement)in caller{rows.insert(name.clone(),crate::Macro{parameters:None,variadic:false,replacement:replacement.clone()});}rows}
 #[test]fn actual_initial_raw_factory_issues_all104_default_products_and_real_assert_interpolation_without_source_forgery(){let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,8<<20,&||Ok(()));let caller=BTreeMap::new();let table=actual_table(&caller);let mut count=0;crate::initial_environment::visit_original_bootstrap_using(crate::InitialEnvironment::OriginalChecker0290,&table,&caller,&a,&mut|input|{let name=input.name();let definition=initial_definition_using(input,&a,&mut|_|panic!("fixed actual defaults have no lexical notices"),&mut|_,_|panic!("fixed actual defaults have no numeric notices"))?;count+=1;assert!(definition.replacement.len()>0);for token in definition.replacement.as_slice(){assert!(token.lexical_frame.is_none());assert!(token.lexical_span.is_none());assert!(!token.origin.invocation);}if name=="TRUE"{assert!(matches!(definition.replacement.as_slice()[0].value,Value::Int(1)));}if name=="ASSERT"{let rows=definition.replacement.as_slice();assert!(rows.iter().any(|t|matches!(t.value,Value::InterpBegin(_))));assert!(rows.iter().any(|t|matches!(t.value,Value::InterpPart(_))));assert!(rows.iter().any(|t|matches!(t.value,Value::InterpEnd(_))));assert!(rows.iter().any(|t|matches!(t.value,Value::Punct("#"))));assert_eq!(definition.parameters.as_ref().unwrap().as_slice()[0].as_str(),"expression");}if name=="EXCEPTION"{assert_eq!(definition.parameters.as_ref().unwrap().as_slice()[0].as_str(),"value");assert!(matches!(&definition.replacement.as_slice()[0].value,Value::Ident{spelling,..}if spelling.get()=="new"));}Ok(())}).unwrap();assert_eq!(count,104);assert_eq!(used.load(Ordering::Acquire),0);}
 #[test]fn actual_caller_template_uses_same_scalar_quote_resource_comment_kernels_and_no_final_newline_or_initial_indent(){let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,8<<20,&||Ok(()));let caller=BTreeMap::from([("EXPONENT".into(),"   1e3".into()),("QUOTE".into(),"\"α\"".into()),("RESOURCE".into(),"'a\\nb'".into()),("CLOSE".into(),"value:key".into()),("DOC".into(),"///actual\n1".into())]);let table=actual_table(&caller);let mut seen=0;crate::initial_environment::visit_original_bootstrap_using(crate::InitialEnvironment::OriginalChecker0290,&table,&caller,&a,&mut|input|{if input.provenance()!=crate::initial_environment::OriginalInitialProvenance::CallerDefinition{return Ok(())}let name=input.name();let definition=initial_definition_using(input,&a,&mut|_|panic!("valid actual template"),&mut|_,_|panic!("valid actual number"))?;let tokens=definition.replacement.as_slice();match name{"EXPONENT"=>{assert_eq!(tokens.len(),1);assert!(matches!(tokens[0].value,Value::Float(n)if n==1000.0));assert_eq!(tokens[0].raw_spelling(),Some("1e3"));},"QUOTE"=>assert!(matches!(&tokens[0].value,Value::String(s)if s.get()=="α")),"RESOURCE"=>assert!(matches!(&tokens[0].value,Value::Resource(s)if s.get()=="anb")),"CLOSE"=>assert!(tokens.iter().any(|t|matches!(t.value,Value::Punct(":"))&&t.punctuation_close)),"DOC"=>assert!(matches!(&tokens[0].value,Value::DocComment{text,..}if text.get()=="actual")),_=>panic!("actual caller row")};assert!(!matches!(tokens.last().unwrap().value,Value::Punct("\n")));seen+=1;Ok(())}).unwrap();assert_eq!(seen,5);assert_eq!(used.load(Ordering::Acquire),0);}
 #[test]fn actual_numeric_recovery_and_precision_notices_do_not_become_missing_products_or_fake_model_none(){let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,8<<20,&||Ok(()));let caller=BTreeMap::from([("BAD".into(),"08".into()),("PRECISION".into(),"2147483648".into())]);let table=actual_table(&caller);let mut events=Vec::new();crate::initial_environment::visit_original_bootstrap_using(crate::InitialEnvironment::OriginalChecker0290,&table,&caller,&a,&mut|input|{if input.provenance()!=crate::initial_environment::OriginalInitialProvenance::CallerDefinition{return Ok(())}let name=input.name();let definition=initial_definition_using(input,&a,&mut|_|panic!("no raw lexical notice"),&mut|point,notice|{let mut text=String::new();notice.write_message(&mut text).unwrap();events.push((name.to_owned(),point.kind(),notice.is_warning(),notice.error_type(),text));Ok(())})?;if name=="BAD"{assert!(matches!(definition.replacement.as_slice()[0].value,Value::Int(0)));}else{assert!(matches!(definition.replacement.as_slice()[0].value,Value::Float(_)));}Ok(())}).unwrap();assert_eq!(events.len(),2);assert!(!events[0].2);assert!(events[0].4.starts_with("bad base-8 integer "));assert!(events[1].2);assert_eq!(events[1].3,Some("integer_precision_loss"));assert_eq!(events[1].4,r#"precision loss of integer constant: "2147483648" to 2147483600"#);assert_eq!(used.load(Ordering::Acquire),0);}
 #[test]fn actual_factory_first_numeric_sink_io_poison_discards_partial_initial_map_and_same_domain_recovers(){let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,8<<20,&||Ok(()));let caller=BTreeMap::from([("BAD".into(),"08".into())]);let table=actual_table(&caller);let mut env=crate::regions::MacroEnvironment::default();let mut numeric_calls=0;let error=env.install_original_initial_using(crate::InitialEnvironment::OriginalChecker0290,&table,&caller,&a,&mut|input,a|initial_definition_using(input,a,&mut|_|Ok(()),&mut|_,_|{numeric_calls+=1;Err(io::Error::from_raw_os_error(1450))})).unwrap_err();assert_eq!(error.raw_os_error(),Some(1450));assert_eq!(numeric_calls,1);assert!(env.is_empty());assert_eq!(used.load(Ordering::Acquire),0);env.install_original_initial_using(crate::InitialEnvironment::OriginalChecker0290,&table,&caller,&a,&mut|input,a|initial_definition_using(input,a,&mut|_|Ok(()),&mut|_,_|Ok(()))).unwrap();let product=env.actual_original_product("BAD").unwrap().unwrap();let definition=product.cloned_definition_using(&a).unwrap();assert!(matches!(definition.replacement.as_slice()[0].value,Value::Int(0)));drop((definition,env));assert_eq!(used.load(Ordering::Acquire),0);}
 #[test]fn same_actual_factory_default_products_match_entire_literal_old_definition_function_not_display_roundtrips(){
  use super::immutable_original_defaults::{self as old,Define};use old::lexer::Token as O;
  let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,8<<20,&||Ok(()));let caller=BTreeMap::new();let table=actual_table(&caller);let original=old::all();assert_eq!(original.len(),104);let mut compared=0;
  crate::initial_environment::visit_original_bootstrap_using(crate::InitialEnvironment::OriginalChecker0290,&table,&caller,&a,&mut|input|{let name=input.name();let actual=initial_definition_using(input,&a,&mut|_|panic!("old fixed products have no lexical notices"),&mut|_,_|panic!("old fixed products have no numeric notices"))?;let expected=&original[name];let expected_tokens=match expected{Define::Constant{subst,..}=>{assert!(actual.parameters.is_none());assert!(!actual.variadic);subst},Define::Function{params,subst,variadic,..}=>{let actual_params=actual.parameters.as_ref().unwrap().as_slice();assert_eq!(actual_params.len(),params.len());for(a,b)in actual_params.iter().zip(params){assert_eq!(a.as_str(),b);}assert_eq!(actual.variadic,*variadic);subst}};assert_eq!(actual.replacement.len(),expected_tokens.len(),"{name}");for(a,b)in actual.replacement.as_slice().iter().zip(expected_tokens){assert!(!a.punctuation_close);match(&a.value,b){(Value::Ident{spelling,whitespace},O::Ident(name,ws))=>{assert_eq!(spelling.get(),name);assert_eq!(whitespace,ws);},(Value::Punct(p),O::Punct(old))=>assert_eq!(*p,old.spelling()),(Value::Int(a),O::Int(b))=>assert_eq!(a,b),(Value::InterpBegin(a),O::InterpStringBegin(b))|(Value::InterpPart(a),O::InterpStringPart(b))|(Value::InterpEnd(a),O::InterpStringEnd(b))=>assert_eq!(a.get(),b),_=>panic!("actual native fixed product token kind differs from literal original: {name}")}}compared+=1;Ok(())}).unwrap();assert_eq!(compared,104);assert_eq!(used.load(Ordering::Acquire),0);
 }
}

#[cfg(test)]mod genuine_string_mode_tests{
 use super::*;use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
 #[test]fn same_native_quote_state_issues_normal_versus_raw_without_raw_display_inference(){let used=Arc::new(AtomicUsize::new(0));let a=SettingAdmission::new(&used,1<<20,&||Ok(()));for (input,mode) in [(b"\"same\\n\"".as_slice(),dm_syntax::OriginalStringMode::Normal),(b"@\"same\\n\"".as_slice(),dm_syntax::OriginalStringMode::Raw)]{let mut lexer=OriginalRawLexer::for_initial_definition(&a).unwrap();let token=lexer.next_using(input,&a,&mut |_|panic!("valid actual quote has no lexical notice"),|event,bytes|project_using(event,bytes,Geometry::InitialDefinition,&a,&mut |_,_|panic!("quote has no numeric notice"))).unwrap().unwrap().unwrap();assert!(matches!(&token.value,Value::String(text)if text.get()=="same\\n"));assert_eq!(token.string_mode,mode);assert_eq!(token.duplicate(&a).unwrap().string_mode,mode);}assert_eq!(used.load(Ordering::Acquire),0);}
}
